<?php
require dirname(__DIR__).'/bootstrap.php';method(['GET','POST']);$u=current_user(true);app_schema();$type=basename(__FILE__,'.php');
if($_SERVER['REQUEST_METHOD']==='GET'){ $p=paging(one('SELECT COUNT(*) n FROM '.table('app_favorite').' WHERE uid=?',[$u['uid']])['n']);$offset=($p['page']-1)*20; $list=rows('SELECT t.tid,t.fid,t.subject,t.author,t.authorid,t.dateline,t.views,t.replies FROM '.table('forum_thread').' t JOIN '.table('app_favorite').' a ON a.tid=t.tid WHERE a.uid=? AND '.thread_where().' ORDER BY a.created DESC LIMIT '.$offset.',20',[$u['uid']]);respond(['list'=>array_map('card',$list),'page'=>$p]); }
$tid=id_input('tid');$t=one('SELECT t.tid FROM '.table('forum_thread').' t WHERE '.thread_where().' AND t.tid=?',[$tid]);if(!$t)respond(null,404,'帖子不可访问');$action=text_input('action',10);if(!in_array($action,['add','remove'],true))respond(null,422,'操作无效');
$table=table('app_'.$type);if($action==='add')exec_sql('INSERT IGNORE INTO '.$table.' (uid,tid,created) VALUES (?,?,?)',[$u['uid'],$tid,time()]);else exec_sql('DELETE FROM '.$table.' WHERE uid=? AND tid=?',[$u['uid'],$tid]);respond(['favorited'=>$action==='add','liked'=>$action==='add','likes'=>(int)one('SELECT COUNT(*) n FROM '.table('app_like').' WHERE tid=?',[$tid])['n']]);
